def slugify(title):
    "Slugify a title string."
    lowercased_title = title.lower()

    slug_characters = []
    for char in lowercased_title:
        if 'a' <= char <= 'z' or '0' <= char <= '9':
            slug_characters.append(char)
        elif char.isspace():
            slug_characters.append('-')

    processed_slug = "".join(slug_characters)

    # Replace runs of hyphens with a single hyphen
    while '--' in processed_slug:
        processed_slug = processed_slug.replace('--', '-')

    # Remove leading/trailing hyphens
    processed_slug = processed_slug.strip('-')

    if not processed_slug:
        return 'untitled'

    return processed_slug
```

